        html = html.replace(/<li>(\s*<input[^>]*type="checkbox")/g, '<li class="md-task">$1');
        // [[_TOC_]]（見 normalizeToc）
        html = html.split(TOC_PLACEHOLDER).join(tocHtml(state.toc, 'md-toc-inline'));
